package com.indiesoundquest.async;
import org.springframework.amqp.core.*; import org.springframework.amqp.rabbit.config.*; import org.springframework.amqp.rabbit.connection.ConnectionFactory; import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.amqp.rabbit.retry.RepublishMessageRecoverer; import org.springframework.context.annotation.*;
@Configuration public class ReportQueueConfiguration { public static final String EXCHANGE="isq.tasks", QUEUE="isq.report-generation", ROUTING_KEY="report.generate", DLX="isq.dlx", DLQ="isq.report-generation.dlq";
 @Bean TopicExchange taskExchange(){return new TopicExchange(EXCHANGE,true,false);} @Bean TopicExchange deadLetterExchange(){return new TopicExchange(DLX,true,false);} @Bean Queue reportQueue(){return QueueBuilder.durable(QUEUE).build();} @Bean Queue deadLetterQueue(){return QueueBuilder.durable(DLQ).build();} @Bean Binding reportBinding(){return BindingBuilder.bind(reportQueue()).to(taskExchange()).with(ROUTING_KEY);}@Bean Binding deadLetterBinding(){return BindingBuilder.bind(deadLetterQueue()).to(deadLetterExchange()).with("report.failed");}
 @Bean SimpleRabbitListenerContainerFactory rabbitListenerContainerFactory(ConnectionFactory connectionFactory,RabbitTemplate template){var f=new SimpleRabbitListenerContainerFactory();f.setConnectionFactory(connectionFactory);f.setDefaultRequeueRejected(false);f.setAdviceChain(RetryInterceptorBuilder.stateless().maxAttempts(3).backOffOptions(1000,2,10000).recoverer(new RepublishMessageRecoverer(template,DLX,"report.failed")).build());return f;}
}
